function sheetSet(id,field,value){
 const s=S.sales.find(x=>String(x.id)===String(id));if(!s)return;
 if(field==='client'){const v=String(value).trim();if(!v)return;s.client=v}
 else if(field==='contact')s.contact=String(value).trim();
 else if(field==='service')s.service=String(value);
 else if(field==='value')s.value=Math.max(0,+value||0);
 else if(field==='date')s.date=String(value);
 else if(field==='stage')s.stage=normalizeLeadStage(value);
 else if(field==='origem'){if(value==='')delete s.origem;else if(ORIGENS.some(o=>o[0]&&o[0]===value))s.origem=value;else return}
 else return;
 save();
}
