async function projectFileAll(){const db=await openClientSiteDB();return new Promise((resolve,reject)=>{const r=db.transaction(PROJECT_FILE_STORE).objectStore(PROJECT_FILE_STORE).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function attachProjectZip(projectId,file){if(!file)return;if(!/\.(zip|html?)$/i.test(file.name))return clientSiteToast('Escolha um arquivo HTML ou ZIP.');const mime=/\.html?$/i.test(file.name)?'text/html':'application/zip';try{const db=await openClientSiteDB(),tx=db.transaction(PROJECT_FILE_STORE,'readwrite'),item={id:uid(),projectId,name:file.name,size:file.size,type:mime,blob:file.slice(0,file.size,mime),updatedAt:new Date().toISOString()};tx.objectStore(PROJECT_FILE_STORE).put(item);await new Promise((ok,no)=>{tx.oncomplete=ok;tx.onerror=()=>no(tx.error)});await drawProjectFiles(projectId);clientSiteToast('Arquivo anexado. Aguarde a confirmação de salvamento online.')}catch(e){clientSiteToast('Falha ao anexar ZIP: '+e.message)}}
