async function previewProjectFile(id){try{const file=(await projectFileAll()).find(item=>String(item.id)===String(id));if(!file||!(file.blob instanceof Blob))return;const url=URL.createObjectURL(file.blob),dialog=document.createElement('dialog');dialog.className='project-preview-dialog';const close=document.createElement('button');close.textContent='Fechar prévia';close.onclick=()=>dialog.close();const frame=document.createElement('iframe');frame.setAttribute('sandbox','');frame.setAttribute('csp',"default-src 'none'; img-src blob: data:; style-src 'unsafe-inline' blob:; font-src blob: data:; script-src 'none'; connect-src 'none'; form-action 'none'; frame-src 'none'");frame.referrerPolicy='no-referrer';frame.title=file.name;frame.srcdoc=await safePreviewDocument(url);dialog.append(close,frame);document.body.append(dialog);dialog.addEventListener('close',()=>{releasePreview(url);dialog.remove()});dialog.showModal()}catch(error){clientSiteToast('Não foi possível abrir o HTML: '+error.message)}}

