// Publicar site na internet (Cloudflare Pages) e ligar o domínio do cliente.
let publishedMap=null,publishedLoading=false;
async function publishApi(body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),75000);try{const response=await fetch('/api/publish',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(body),signal:controller.signal});const data=await response.json().catch(()=>({}));if(response.status===401){location.assign('/acesso.html');throw new Error('Sessão encerrada.')}if(!response.ok){const error=new Error(data.error||'Não foi possível concluir a operação.');error.code=data.code||'';throw error}return data}catch(e){if(e.name==='AbortError')throw new Error('Demorou demais. Confira o site no painel da Cloudflare ou tente de novo.');throw e}finally{clearTimeout(timer)}}
// Lista de sites no ar: carregada uma única vez por abertura do painel (sem atualização automática).
function ensurePublished(){if(publishedMap||publishedLoading)return;publishedLoading=true;publishApi({action:'list'}).then(data=>{publishedMap=new Map(Object.entries(data.items||{}));if(publishedMap.size){if(tab==='clients')drawClients();else if(tab==='mySites')drawClientSites()}}).catch(()=>{publishedMap=new Map()}).finally(()=>{publishedLoading=false})}
const publishBadgeHtml=id=>publishedMap?.has(String(id))?'<span class="demo-badge is-sent">🌐 No ar</span>':'';
window.promisaOpenPublish=key=>openPublish(key);
async function openPublish(key){
 await loadSiteRows();const site=clientSiteRows.find(x=>x.id===key);if(!site)return;
 const el=(tag,cls,text)=>{const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node};
 const btn=(label,cls,fn)=>{const b=el('button',cls,label);b.type='button';b.addEventListener('click',fn);return b};
 const dialog=el('dialog','project-preview-dialog demo-links-dialog');dialog.setAttribute('aria-label','Publicar site');dialog.addEventListener('close',()=>dialog.remove());
 const head=el('div','demo-links-head');head.append(el('h2','','🌐 Publicar site'),el('p','demo-links-site',site.name||'Site'));
 const box=el('div','pub-box');
 const close=el('button','sec demo-links-close','Fechar');close.type='button';close.addEventListener('click',()=>dialog.close());
 const dataBox=el('div','pub-data');dialog.append(head,box,dataBox,close);document.body.append(dialog);dialog.showModal();window.promisaSiteData?.mount(dataBox,String(site.id),()=>publishedMap?.get(String(site.id))?.url||'');
 const note=(text,cls='demo-help')=>{const p=el('p',cls,text);p.setAttribute('role','status');return p};
 const copyRow=(value,label)=>{const row=el('div','demo-link-row');const input=el('input');input.readOnly=true;input.value=value;input.setAttribute('aria-label',label);input.addEventListener('focus',()=>input.select());const actions=el('div','demo-link-actions');actions.append(btn('Copiar','',()=>copy(value)));row.append(input,actions);return row};
 const show=(...nodes)=>box.replaceChildren(...nodes);
 const fail=error=>{if(error.code==='cloudflare-not-configured')show(el('p','pub-warn','A publicação ainda não foi configurada. Falta colocar a chave da Cloudflare na Vercel.'),note('Quando a chave estiver na Vercel, abra esta janela de novo.'));else show(el('p','pub-warn',error.message),btn('Tentar de novo','sec',()=>load()))};
 const waitSync=async()=>{if(!window.promisaCloud?.hasPending())return true;try{await window.promisaCloud.sync(true)}catch{}for(let i=0;i<10&&window.promisaCloud.hasPending();i++)await new Promise(r=>setTimeout(r,500));return !window.promisaCloud.hasPending()};
 const run=async(button,label,work)=>{button.disabled=true;const old=button.textContent;button.textContent=label;try{await work()}catch(e){clientSiteToast(e.message);button.disabled=false;button.textContent=old}};
 const publish=async(button,domain)=>run(button,'Publicando… pode levar até 1 minuto',async()=>{
  if(!await waitSync()){button.disabled=false;button.textContent='Publicar agora';return clientSiteToast('Aguarde o indicador "Salvo online" e tente de novo.')}
  const data=await publishApi({action:'publish',siteId:String(site.id),...(domain?{domain}:{})});
  publishedMap??=new Map();publishedMap.set(String(site.id),data);clientSiteToast('Site publicado.');await load(data.domainInfo)});
 function domainSection(data,info){
  const sec=el('div','pub-domain');sec.append(el('h3','','Domínio do cliente'));
  const domains=data.live?.domains||[],zone=data.live?.zone||(info?.zone?{status:info.zone.status,nameServers:info.zone.nameServers}:null);
  if(data.domain){
   const ok=zone?.status==='active'&&domains.length>0&&domains.every(d=>d.status==='active');
   if(ok)sec.append(el('p','pub-ok','✅ No ar em https://'+data.domain));
   else{
    sec.append(el('p','pub-wait','⏳ Aguardando o domínio (pode levar de 1 a 24 horas)'));
    const ns=(zone?.nameServers?.length?zone.nameServers:data.nameServers)||[];
    if(zone?.status!=='active'&&ns.length){
     const steps=el('div','pub-steps');
     steps.append(el('p','','Falta um passo no lugar onde o domínio foi comprado. É só trocar os "servidores DNS" por estes dois:'));
     for(const n of ns)steps.append(copyRow(n,'Servidor DNS'));
     const reg=el('p','demo-help');reg.append(document.createTextNode('Registro.br: entre no '));const a=el('a','','painel do Registro.br');a.href='https://registro.br/painel/';a.target='_blank';a.rel='noopener noreferrer';reg.append(a,document.createTextNode(' → seu domínio → DNS → "Alterar servidores DNS" e coloque estes dois.'));
     steps.append(reg,note('Hostinger: Domínios → seu domínio → DNS / Nameservers → "Alterar nameservers" e coloque estes dois.'));
     sec.append(steps);
    }
   }
   sec.append(btn('Verificar agora','sec',async function(){this.disabled=true;await load(info)}));
  }
  const ex=info?.records?.conflicts||[];
  if(ex.length)sec.append(el('p','pub-warn','Atenção: já existem endereços antigos neste domínio ('+ex.map(c=>c.name+' '+c.type).join(', ')+'). Não apagamos nada. Peça ajuda antes de continuar, senão o site novo pode não aparecer.'));
  const form=el('form','demo-links-form');const label=el('label','','Domínio do cliente (ex.: chicomoveis.com.br)');const input=el('input');input.type='text';input.placeholder='chicomoveis.com.br';input.autocomplete='off';input.value=data.domain||'';label.append(input);
  const go=el('button','sec',data.domain?'Trocar domínio':'Ligar domínio');go.type='submit';form.append(label,go);
  form.addEventListener('submit',event=>{event.preventDefault();run(go,'Ligando…',async()=>{const res=await publishApi({action:'set-domain',siteId:String(site.id),domain:input.value});clientSiteToast('Domínio ligado. Agora siga os passos abaixo.');await load(res.domainInfo)})});
  sec.append(form);return sec;
 }
 async function load(info){
  show(note('Carregando…'));
  try{
   const data=await publishApi({action:'status',siteId:String(site.id)});
   if(!data.published){
    publishedMap?.delete(String(site.id));
    const go=el('button','','Publicar agora');go.type='button';go.addEventListener('click',()=>publish(go));
    show(el('p','demo-links-info','O site vai para a internet num endereço grátis (…pages.dev). Depois você pode ligar o domínio do cliente.'),...(window.promisaCloud?.hasPending()?[note('Há alterações ainda não enviadas. Vamos esperar o "Salvo online" antes de publicar.')]:[]),go);return;
   }
   publishedMap??=new Map();publishedMap.set(String(site.id),data);
   const nodes=[el('p','pub-ok','✅ O site está na internet.'),copyRow(data.url,'Endereço do site')];
   const open=btn('Abrir','sec',()=>window.open(data.url,'_blank','noopener,noreferrer'));nodes[1].querySelector('.demo-link-actions').append(open);
   nodes.push(el('p','demo-link-meta','Publicado em '+demoLinkDate(data.lastPublishedAt)));
   if(data.liveError)nodes.push(note(data.liveError));
   if(data.outdated)nodes.push(el('p','pub-warn','⚠️ Há mudanças não publicadas. Clique em "Atualizar site" para mostrar a versão nova.'));
   const upd=el('button',data.outdated?'':'sec','Atualizar site');upd.type='button';upd.addEventListener('click',()=>publish(upd));
   const off=btn('Tirar do ar','sec danger',()=>{if(!confirm('Tirar este site do ar? O endereço deixa de funcionar. Você pode publicar de novo depois.'))return;run(off,'Tirando do ar…',async()=>{await publishApi({action:'unpublish',siteId:String(site.id)});publishedMap?.delete(String(site.id));clientSiteToast('Site tirado do ar.');await load()})});
   nodes.push(upd,domainSection(data,info),off);
   show(...nodes);
  }catch(e){fail(e)}
 }
 await load();
}
