function downloadClientBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function mergeBackupArray(current,incoming){const out=Array.isArray(current)?current.slice():[];for(const raw of incoming){if(!raw||typeof raw!=='object'){if(!out.some(x=>JSON.stringify(x)===JSON.stringify(raw)))out.push(raw);continue}const sameId=raw.id==null?-1:out.findIndex(x=>x&&String(x.id)===String(raw.id));if(sameId>=0){if(JSON.stringify(out[sameId])!==JSON.stringify(raw))throw new Error('Há registros diferentes com o mesmo identificador. Resolva o conflito antes de restaurar para preservar os vínculos.');continue}if(!out.some(x=>JSON.stringify(x)===JSON.stringify(raw)))out.push(raw)}return out}
function mergeFullErpData(incoming){const merged={...incoming,...S};for(const key of new Set([...Object.keys(incoming),...Object.keys(S)])){const a=incoming[key],b=S[key];if(key==='prospectNotes'&&typeof a==='string'&&typeof b==='string'){merged[key]=!a||a===b||b.includes(a)?b:!b?a:b+'\n\n--- Anotações do backup ---\n'+a;continue}if(Array.isArray(a))merged[key]=mergeBackupArray(b,a);else if(a&&b&&typeof a==='object'&&typeof b==='object'&&!Array.isArray(b)){const defaults=key==='plan'?{meta:'',ticket:'',conv:'20',pacotes:'',publico:'',dif:'',obs:''}:{};const obj={...a,...b};for(const k of Object.keys(a))if((obj[k]===undefined||obj[k]===null||obj[k]===''||(key==='plan'&&obj[k]===defaults[k]))&&a[k]!==undefined)obj[k]=a[k];merged[key]=obj}else if(b===undefined||b===null||b==='')merged[key]=a}if(Array.isArray(merged.sales))for(const lead of merged.sales)lead.stage=normalizeLeadStage(lead.stage);return merged}
function clientSiteFileSignature(site){return JSON.stringify({htmlPath:clientSitePath(site.htmlPath||''),files:(site.files||[]).map(f=>({...f,path:clientSitePath(f.path)}))})}
function clientSiteProjectSignature(site){return JSON.stringify({name:site.name||'',clientName:site.clientName||'',content:clientSiteFileSignature(site)})}
function notesPage(){return `<h1>Anotações</h1><p class="sub">Seu bloco de notas para possíveis clientes, contatos e lembretes.</p><div class="card notes-card"><label for="prospectNotes"><b>Possíveis clientes e ideias</b></label><p class="lead-muted notes-hint">Escreva um nome por linha ou organize como preferir. Exemplo: Loja do João — pedir contato e apresentar o site.</p><textarea id="prospectNotes" class="notes-editor" aria-describedby="notesSaveStatus" placeholder="Nome do cliente ou empresa
Contato
O que conversar / próximo passo

Próximo possível cliente..." data-input="saveProspectNotes" data-input-args="[]" data-input-value="value">${esc(typeof S.prospectNotes==='string'?S.prospectNotes:'')}</textarea><small id="notesSaveStatus" class="lead-muted" role="status">Salvamento automático. Confira o indicador de sincronização online no topo.</small></div>`}
function saveProspectNotes(text){S.prospectNotes=text;const status=document.getElementById('notesSaveStatus');try{localStorage.setItem(K,JSON.stringify(S));window.promisaCloud?.changed();if(status)status.textContent='Salvo neste aparelho · aguardando sincronização online.'}catch(e){if(status)status.textContent='Não foi possível salvar no navegador. Mantenha esta página aberta e copie seu texto antes de sair.'}}
function backupPage(){return `<h1>Backup geral</h1><p class="sub">Todos os seus dados em um único arquivo, para guardar ou transferir entre o computador e o celular.</p><div class="card"><h2 style="margin-top:0">Tudo incluído</h2><p>Leads e contatos, vendas, despesas, projetos pessoais, anotações, plano de negócios, configurações, sites dos clientes e seus sites pessoais, com todos os arquivos anexados.</p><p id="backupSummary" class="site-count" role="status">Carregando dados dos sites…</p><div class="site-toolbar"><button id="backupExport" data-click="runGeneralBackup" data-click-args="[&quot;export&quot;]">Baixar backup geral</button><button id="backupRestore" class="sec" data-click="pickFile" data-click-args='["generalBackupInput"]'>Restaurar backup</button></div><input id="generalBackupInput" type="file" accept=".json,application/json" hidden data-change="runGeneralBackupClear" data-change-args="[&quot;restore&quot;]" data-change-value="file"></div><div class="card" id="discordBackupCard"></div><div class="card"><h2 style="margin-top:0">Como levar para outro aparelho</h2><p>1. Baixe o backup geral e guarde o arquivo JSON.</p><p>2. Envie esse arquivo para o outro aparelho e abra o Promisa nele.</p><p>3. Entre em Backup e escolha Restaurar backup.</p><small class="lead-muted">A restauração mescla o backup com os dados atuais, preservando os registros já existentes. Backups antigos também podem ser importados aqui. A cópia local fica no navegador; os dados também são sincronizados quando o armazenamento online está configurado.</small></div>`}
async function drawBackupSummary(){const el=document.getElementById('backupSummary');if(!el)return;try{const db=await openClientSiteDB(),count=await new Promise((ok,no)=>{const r=db.transaction(SITE_STORE).objectStore(SITE_STORE).count();r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});el.textContent=(S.sales||[]).length+' lead(s) · '+(S.projects||[]).length+' projeto(s) · '+count+' site(s) guardado(s). Os anexos serão lidos apenas ao exportar.'}catch{el.textContent='Não foi possível consultar o armazenamento dos sites.'}}
let generalBackupBusy=false;
async function runGeneralBackup(action,file){if(generalBackupBusy||action==='restore'&&!file)return;generalBackupBusy=true;const buttons=['backupExport','backupRestore'].map(id=>document.getElementById(id));buttons.forEach(b=>{if(b)b.disabled=true});try{if(action==='export')await exportFullBackup();else{const data=await readBackup(file);if(data.format==='promisa-erp-completo')await restoreFullBackup(file);else if(['promisa-client-sites','arquivo-de-sites','arquivo-sites','arquivo-sites-v1'].includes(data.format)&&Array.isArray(data.sites))await restoreClientSites(file);else if(Array.isArray(data.sales)&&Array.isArray(data.exp)){const merged=mergeFullErpData(promisaValidation.validateState(data));localStorage.setItem(K,JSON.stringify(merged));S=merged;save();render();clientSiteToast('Backup antigo importado. Os dados atuais foram preservados.')}else throw new Error('Arquivo de backup incompatível.')}await drawBackupSummary()}catch(e){alert('Não foi possível processar o backup: '+e.message)}finally{generalBackupBusy=false;['backupExport','backupRestore'].forEach(id=>{const b=document.getElementById(id);if(b)b.disabled=false})}}
async function exportFullBackup(){
 const data={format:'promisa-erp-completo',version:2,createdAt:new Date().toISOString(),erp:promisaValidation.validateState(S),sites:await promisaValidation.encodeValue(await clientSiteAll()),projectAttachments:await promisaValidation.encodeValue(await projectFileAll())};
 downloadClientBlob(new Blob([JSON.stringify(data)],{type:'application/json'}),`backup-completo-promisa-${today()}.json`);
 clientSiteToast('Backup completo gerado, incluindo os ZIPs originais. O arquivo contém dados privados: guarde-o em local protegido.');
}
async function restoreFullBackup(file){
 if(!file)return;
 const data=await readBackup(file);
 if(data.format!=='promisa-erp-completo'||![1,2].includes(data.version)||!Array.isArray(data.sites))throw new Error('Backup geral incompatível.');
 const incoming=promisaValidation.validateState(data.erp);
 const sites=(data.version===2?promisaValidation.decodeValue(data.sites):data.sites).map(site=>promisaValidation.validateRecord('sites',site));
 let attachments;
 if(data.version===2)attachments=promisaValidation.decodeValue(data.projectAttachments||[]);
 else attachments=await Promise.all((data.projectAttachments||[]).map(async item=>{
  if(typeof item.data!=='string'||!/^data:[^,]*;base64,/i.test(item.data))throw new Error('Anexo legado inválido: somente conteúdo embutido é aceito.');
  const blob=await(await fetch(item.data)).blob();return {...item,blob:new Blob([blob],{type:item.type||(/\.html?$/i.test(item.name)?'text/html':'application/zip')})};
 }));
 attachments=attachments.map(item=>promisaValidation.validateRecord('attachments',item));
 // Complete validation before any persistent write. Duplicate IDs are rejected, never partially restored.
 for(const items of [sites,attachments])if(new Set(items.map(item=>item.id)).size!==items.length)throw new Error('Identificadores duplicados no backup.');
 if(!confirm('Mesclar este backup com os dados atuais? Uma cópia de segurança será baixada antes de continuar.'))return;
 await exportFullBackup();
 const currentSites=await clientSiteAll(),currentFiles=await projectFileAll();
 const siteIds=new Set(currentSites.map(item=>String(item.id))),fileIds=new Set(currentFiles.map(item=>String(item.id)));
 // Keep existing IDs to avoid breaking project/site links; conflicts require an explicit separate restore.
 for(const item of sites)if(siteIds.has(item.id)&&JSON.stringify(await promisaValidation.encodeValue(currentSites.find(x=>String(x.id)===item.id)))!==JSON.stringify(await promisaValidation.encodeValue(item)))throw new Error('Há um site diferente com o mesmo identificador. Use uma cópia do aparelho ou resolva o conflito antes de restaurar.');
 for(const item of attachments)if(fileIds.has(item.id)&&JSON.stringify(await promisaValidation.encodeValue(currentFiles.find(x=>String(x.id)===item.id)))!==JSON.stringify(await promisaValidation.encodeValue(item)))throw new Error('Há um anexo diferente com o mesmo identificador.');
 const merged=promisaValidation.validateState(mergeFullErpData(incoming)),old=localStorage.getItem(K),db=await openClientSiteDB();
 const tx=db.transaction([SITE_STORE,PROJECT_FILE_STORE],'readwrite'),done=transactionDone(tx);
 try{
  for(const item of sites)if(!siteIds.has(item.id))tx.objectStore(SITE_STORE).put(item);
  for(const item of attachments)if(!fileIds.has(item.id))tx.objectStore(PROJECT_FILE_STORE).put(item);
  localStorage.setItem(K,JSON.stringify(merged));await done;
 }catch(error){try{tx.abort()}catch{}await done.catch(()=>{});if(old===null)localStorage.removeItem(K);else localStorage.setItem(K,old);throw error}
 S=merged;save();render();clientSiteToast('Backup validado e restaurado. Aguarde a confirmação de sincronização.');
}
async function restoreClientSites(file){
 const data=await readBackup(file);
 if(!['promisa-client-sites','arquivo-de-sites','arquivo-sites','arquivo-sites-v1'].includes(data.format)||!Array.isArray(data.sites))throw new Error('Backup de sites incompatível.');
 const sites=data.sites.map(raw=>promisaValidation.validateRecord('sites',{...raw,id:clientSiteId(),siteType:raw.siteType==='pessoal'?'pessoal':'cliente',htmlPath:raw.htmlPath||raw.files?.find(item=>/\.html?$/i.test(item.path))?.path}));
 if(!confirm('Importar os sites deste backup? Os dados existentes serão preservados.'))return;
 const db=await openClientSiteDB(),tx=db.transaction(SITE_STORE,'readwrite'),done=transactionDone(tx);
 for(const site of sites)tx.objectStore(SITE_STORE).put(site);
 await done;await drawClientSites();clientSiteToast('Sites restaurados e aguardando sincronização.');
}
